{
  "items": [
    {
      "name": "RingSeminorm.mul_le'",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.RingSeminorm",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : NonUnitalNonAssocRing R] (self : RingSeminorm R) (x y : R),\n  self.toFun (x * y) ≤ self.toFun x * self.toFun y"
    },
    {
      "name": "MvPolynomial.eval_eq",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (X : σ → R) (f : MvPolynomial σ R),\n  (MvPolynomial.eval X) f = ∑ d ∈ f.support, MvPolynomial.coeff d f * ∏ i ∈ d.support, X i ^ d i"
    },
    {
      "name": "Polynomial.eval₂_eq_sum_range'",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : Semiring S] (f : R →+* S) {p : Polynomial R} {n : ℕ},\n  p.natDegree < n → ∀ (x : S), Polynomial.eval₂ f x p = ∑ i ∈ Finset.range n, f (p.coeff i) * x ^ i"
    },
    {
      "name": "Polynomial.eval_eq_sum_range'",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R} {n : ℕ},\n  p.natDegree < n → ∀ (x : R), Polynomial.eval x p = ∑ i ∈ Finset.range n, p.coeff i * x ^ i"
    },
    {
      "name": "seminormFromBounded_ge",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.SeminormFromBounded",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {f : R → ℝ} {c : ℝ},\n  0 ≤ f → (∀ (x y : R), f (x * y) ≤ c * f x * f y) → ∀ (x : R), f x ≤ f 1 * seminormFromBounded' f x"
    },
    {
      "name": "seminormFromBounded_mul",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.SeminormFromBounded",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {f : R → ℝ} {c : ℝ},\n  0 ≤ f →\n    (∀ (x y : R), f (x * y) ≤ c * f x * f y) →\n      ∀ (x y : R), seminormFromBounded' f (x * y) ≤ seminormFromBounded' f x * seminormFromBounded' f y"
    },
    {
      "name": "MulRingSeminorm.map_mul'",
      "module_name": "Mathlib.Analysis.Normed.Unbundled.RingSeminorm",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : NonAssocRing R] (self : MulRingSeminorm R) (x y : R),\n  self.toFun (x * y) = self.toFun x * self.toFun y"
    }
  ]
}

{
  "items": [
    {
      "name": "Polynomial.eval₂_homogenize_of_eq_one",
      "type": " {R : Type u_1} [CommSemiring R] {S : Type u_2} [CommSemiring S] {p : Polynomial R} {n : ℕ} (hn : p.natDegree ≤ n) (f : R →+* S) (g : Fin 2 → S) (hg : g 1 = 1) : MvPolynomial.eval₂ f g (p.homogenize n) = Polynomial.eval₂ f (g 0) p",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    }
  ]
}
